<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Result card · {{ $student->name }}</title><style>
*{box-sizing:border-box}body{margin:28px;color:#111;font:13px Arial,sans-serif}.toolbar{display:flex;justify-content:space-between;margin-bottom:20px}.toolbar a,.toolbar button{padding:9px 14px;background:#102d4f;color:#fff;border:0;text-decoration:none;cursor:pointer}.heading{text-align:center;margin:20px 0}.heading h1{font-size:18px;background:#000;color:white;padding:8px}.student{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:14px;background:#eee;margin:20px 0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #111;padding:8px;text-align:center}th{background:#ddd}.signatures{display:flex;justify-content:space-between;margin-top:65px}.signatures span{border-top:1px solid #222;padding:7px 18px}@media print{body{margin:12mm}.toolbar{display:none}tr{break-inside:avoid}}
</style></head><body>@include('documents.partials.letterhead-print-background')<div class="toolbar"><a href="{{ route('examination.result-sheet', ['class_id' => $student->class_id, 'month' => $month]) }}">Back to class results</a><button onclick="window.print()">Print result card</button></div><header class="heading"><strong>{{ $academy?->name ?? 'Academy' }}</strong><p>{{ $academy?->address ?? '' }}</p><h1>Student Result Card</h1><strong>{{ \Illuminate\Support\Carbon::createFromFormat('Y-m', $month)->format('F Y') }}</strong></header><div class="student"><div>Student: <strong>{{ $student->name }}</strong></div><div>Student ID: <strong>{{ $student->admission_no }}</strong></div><div>Father / guardian: <strong>{{ $student->father_name }}</strong></div><div>Class / section: <strong>{{ $student->academyClass?->name }} · {{ $student->academyClass?->section }}</strong></div></div><table><thead><tr><th>Subject</th><th>Test</th><th>Total marks</th><th>Pass marks</th><th>Marks obtained</th><th>Status</th></tr></thead><tbody>@php($total = 0)@php($possible = 0)@foreach ($examinations as $exam)@php($mark = $exam->results->firstWhere('student_id', $student->id))@if ($mark && (float) $mark->marks_obtained >= 0)@php($total += (float) $mark->marks_obtained)@php($possible += (float) $exam->total_marks)@endif<tr><td>{{ $exam->subject }}</td><td>{{ $exam->title }}</td><td>{{ $exam->total_marks }}</td><td>{{ $exam->passing_marks }}</td><td>{{ $mark ? ((float) $mark->marks_obtained < 0 ? 'Absent' : $mark->marks_obtained) : 'Not entered' }}</td><td>{{ $mark ? ((float) $mark->marks_obtained < 0 ? 'Absent' : ((float) $mark->marks_obtained >= (float) $exam->passing_marks ? 'Pass' : 'Fail')) : '—' }}</td></tr>@endforeach</tbody></table><p style="text-align:right;margin-top:18px"><strong>Total: {{ $total }} / {{ $possible }} · Percentage: {{ $possible > 0 ? number_format($total / $possible * 100, 2).'%' : '—' }}</strong></p><div class="signatures"><span>Class teacher</span><span>Principal</span><span>Parent</span></div><script>window.addEventListener('load',()=>window.print())</script></body></html>
